-- | mulUInt8: UInt8 -> UInt8 -> Either OverflowError UInt8.
--   Both operands are 0..255 so an i32 multiply gives 0..65025 — well
--   inside i32 range. A single 'i32.gt_u 255' check selects the branch.
rtMulU8 :: PreludeTags -> Text
rtMulU8 ptags =
  unlines
    [ "  (func $__mulUInt8 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $p i32) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $p (i32.mul (i32.load (local.get $pa)) (i32.load (local.get $pb))))",
      "    (if (result i32) (i32.gt_u (local.get $p) (i32.const 255))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const " <> tShow (ptOverflowError ptags) <> "))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (local.get $p))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | splitOnFirst: String -> String -> Maybe (Tuple2 String String).
--   WASM has no built-in substring search, so we hand-roll a byte-by-byte
--   scan: outer 'i' loop walks `0..str_len - sep_len`, inner 'j' loop
--   compares `sep[j]` against `str[i + j]` until either a mismatch
--   (advance i) or full match (capture pos, break). Empty separator is
--   handled implicitly: the inner loop runs zero times, $match stays 1,
--   the first iteration of the outer loop returns position 0. Separator
--   longer than `str` is also implicit: the outer loop's bound check
--   fails on the first iteration, returning Nothing.
--   Container layout matches the rest of this file:
--     Maybe Nothing : 1-slot cell [tag=0]
--     Maybe Just    : 2-slot cell [tag=1, payload]
--     Tuple2        : 3-slot cell [tag=0, prefix, suffix]
rtSplitOnFirst :: PreludeTags -> Text
rtSplitOnFirst ptags =
  unlines
    [ "  (func $__splitOnFirst (param $sep i32) (param $str i32) (result i32)",
      "    (local $sep_len i32) (local $str_len i32)",
      "    (local $sep_payload i32) (local $str_payload i32)",
      "    (local $i i32) (local $j i32) (local $pos i32) (local $match i32)",
      "    (local $prefix i32) (local $suffix i32) (local $tuple i32) (local $cell i32)",
      "    (local $suf_len i32) (local $u16 i32)",
      "    (local.set $sep_len (i32.load (local.get $sep)))",
      "    (local.set $str_len (i32.load (local.get $str)))",
      "    (local.set $sep_payload (i32.add (local.get $sep) (i32.const 8)))",
      "    (local.set $str_payload (i32.add (local.get $str) (i32.const 8)))",
      "    (local.set $pos (i32.const -1))",
      "    (local.set $i (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        ;; if i + sep_len > str_len: not found, break",
      "        (br_if $break",
      "          (i32.gt_u",
      "            (i32.add (local.get $i) (local.get $sep_len))",
      "            (local.get $str_len)))",
      "        ;; check whether sep matches at position i",
      "        (local.set $j (i32.const 0))",
      "        (local.set $match (i32.const 1))",
      "        (block $check_break",
      "          (loop $check_loop",
      "            (br_if $check_break (i32.eq (local.get $j) (local.get $sep_len)))",
      "            (if (i32.ne",
      "                  (i32.load8_u (i32.add (local.get $str_payload) (i32.add (local.get $i) (local.get $j))))",
      "                  (i32.load8_u (i32.add (local.get $sep_payload) (local.get $j))))",
      "              (then",
      "                (local.set $match (i32.const 0))",
      "                (br $check_break)))",
      "            (local.set $j (i32.add (local.get $j) (i32.const 1)))",
      "            (br $check_loop)))",
      "        (if (local.get $match)",
      "          (then",
      "            (local.set $pos (local.get $i))",
      "            (br $break)))",
      "        (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "        (br $loop)))",
      "    (if (result i32) (i32.eq (local.get $pos) (i32.const -1))",
      "      (then",
      "        (local.set $cell (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptNothing ptags) <> "))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $prefix (call $__alloc (i32.add (local.get $pos) (i32.const 8))))",
      "        (i32.store (local.get $prefix) (local.get $pos))",
      "        (local.set $u16 (call $__utf16_of_range (local.get $str_payload) (local.get $pos)))",
      "        (i32.store offset=4 (local.get $prefix) (local.get $u16))",
      "        (call $__memcpy (i32.add (local.get $prefix) (i32.const 8)) (local.get $str_payload) (local.get $pos))",
      "        (local.set $suf_len (i32.sub (i32.sub (local.get $str_len) (local.get $pos)) (local.get $sep_len)))",
      "        (local.set $suffix (call $__alloc (i32.add (local.get $suf_len) (i32.const 8))))",
      "        (i32.store (local.get $suffix) (local.get $suf_len))",
      "        (local.set $u16 (call $__utf16_of_range",
      "                            (i32.add (local.get $str_payload) (i32.add (local.get $pos) (local.get $sep_len)))",
      "                            (local.get $suf_len)))",
      "        (i32.store offset=4 (local.get $suffix) (local.get $u16))",
      "        (call $__memcpy",
      "          (i32.add (local.get $suffix) (i32.const 8))",
      "          (i32.add (local.get $str_payload) (i32.add (local.get $pos) (local.get $sep_len)))",
      "          (local.get $suf_len))",
      "        (local.set $tuple (call $__alloc (i32.const 12)))",
      "        (i32.store (local.get $tuple) (i32.const " <> tShow (ptTuple2 ptags) <> "))",
      "        (i32.store offset=4 (local.get $tuple) (local.get $prefix))",
      "        (i32.store offset=8 (local.get $tuple) (local.get $suffix))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptJust ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $tuple))",
      "        (local.get $cell))))"
    ]

-- | lengthUtf8Bytes : String -> UInt32. O(1) load from the header at
--   offset 0 (was an O(n) byte scan via '__strlen' on the old null-term
--   layout).
rtLengthBytesAsUtf8 :: Text
rtLengthBytesAsUtf8 =
  unlines
    [ "  (func $__lengthUtf8Bytes (param $s i32) (result i32)",
      "    (local $box i32)",
      "    (local.set $box (call $__alloc (i32.const 4)))",
      "    (i32.store (local.get $box) (i32.load (local.get $s)))",
      "    (local.get $box))"
    ]

-- | lengthCodePoints : String -> UInt32. Still O(n) — code-point count
--   needs a byte walk (one increment per non-continuation byte). The
--   walk is now bounded by the byte_count from the header rather than
--   terminated by NUL, so a payload containing NUL is counted correctly.
rtLengthCodePoints :: Text
rtLengthCodePoints =
  unlines
    [ "  (func $__lengthCodePoints (param $s i32) (result i32)",
      "    (local $bytes i32) (local $payload i32)",
      "    (local $i i32) (local $n i32) (local $b i32) (local $box i32)",
      "    (local.set $bytes (i32.load (local.get $s)))",
      "    (local.set $payload (i32.add (local.get $s) (i32.const 8)))",
      "    (local.set $i (i32.const 0))",
      "    (local.set $n (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        (br_if $break (i32.ge_u (local.get $i) (local.get $bytes)))",
      "        (local.set $b (i32.load8_u (i32.add (local.get $payload) (local.get $i))))",
      "        (if (i32.ne (i32.and (local.get $b) (i32.const 0xC0)) (i32.const 0x80))",
      "          (then (local.set $n (i32.add (local.get $n) (i32.const 1)))))",
      "        (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "        (br $loop)))",
      "    (local.set $box (call $__alloc (i32.const 4)))",
      "    (i32.store (local.get $box) (local.get $n))",
      "    (local.get $box))"
    ]

-- | lengthUtf16CodeUnits : String -> UInt32. O(1) load from the header
--   at offset 4 (was an O(n) byte scan with surrogate-pair counting on
--   the old null-term layout).
rtLengthUtf16CodeUnits :: Text
rtLengthUtf16CodeUnits =
  unlines
    [ "  (func $__lengthUtf16CodeUnits (param $s i32) (result i32)",
      "    (local $box i32)",
      "    (local.set $box (call $__alloc (i32.const 4)))",
      "    (i32.store (local.get $box) (i32.load offset=4 (local.get $s)))",
      "    (local.get $box))"
    ]

-- | parseInt32 : String -> Either ParseError Int32. Handrolled byte
--   scan; same algorithm as the LLVM, JVM, and CLR helpers — i64
--   accumulator capped at the magnitude `|minInt32|`. The constant
--   2147483648 is built with the shift trick `1 << 31` (avoids needing
--   a separate i64 literal in the binary). On any failure path we set
--   the `$failed` flag and `br $exit` out of the parsing block; result
--   construction (Right or Left) happens after the block based on the
--   flag.
rtParseInt32 :: PreludeTags -> Text
rtParseInt32 ptags =
  unlines
    [ "  (func $__parseInt32 (param $s i32) (result i32)",
      "    (local $len i32) (local $i i32) (local $neg i32) (local $payload i32)",
      "    (local $c i32) (local $box i32) (local $cell i32) (local $pe i32)",
      "    (local $failed i32) (local $acc i64)",
      "    (local.set $failed (i32.const 0))",
      "    (local.set $acc (i64.const 0))",
      "    (local.set $len (i32.load (local.get $s)))",
      "    (local.set $payload (i32.add (local.get $s) (i32.const 8)))",
      "    (block $exit",
      "      (if (i32.eqz (local.get $len))",
      "        (then (local.set $failed (i32.const 1)) (br $exit)))",
      "      (local.set $i (i32.const 0))",
      "      (local.set $neg (i32.const 0))",
      "      (if (i32.eq (i32.load8_u (local.get $payload)) (i32.const 45))",
      "        (then",
      "          (local.set $neg (i32.const 1))",
      "          (local.set $i (i32.const 1))",
      "          (if (i32.eq (local.get $len) (i32.const 1))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))))",
      "      (block $loop_break",
      "        (loop $loop",
      "          (br_if $loop_break (i32.ge_u (local.get $i) (local.get $len)))",
      "          (local.set $c (i32.load8_u (i32.add (local.get $payload) (local.get $i))))",
      "          (if (i32.lt_u (local.get $c) (i32.const 48))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (if (i32.gt_u (local.get $c) (i32.const 57))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $acc",
      "            (i64.add",
      "              (i64.mul (local.get $acc) (i64.const 10))",
      "              (i64.extend_i32_u (i32.sub (local.get $c) (i32.const 48)))))",
      "          (if (i64.gt_s (local.get $acc) (i64.shl (i64.const 1) (i64.const 31)))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "          (br $loop)))",
      "      (if (local.get $neg)",
      "        (then (local.set $acc (i64.sub (i64.const 0) (local.get $acc))))",
      "        (else",
      "          (if (i64.gt_s (local.get $acc) (i64.const 2147483647))",
      "            (then (local.set $failed (i32.const 1)) (br $exit))))))",
      "    (if (result i32) (local.get $failed)",
      "      (then",
      "        (local.set $pe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $pe) (i32.const " <> tShow (ptParseError ptags) <> "))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $pe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.wrap_i64 (local.get $acc)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | parseUInt8 : String -> Either ParseError UInt8. Same shape as
--   'rtParseInt32' minus the sign handling, with an i32 accumulator
--   (the running magnitude never exceeds 2559 before the > 255 check
--   fails the parse).
rtParseUInt8 :: PreludeTags -> Text
rtParseUInt8 ptags =
  unlines
    [ "  (func $__parseUInt8 (param $s i32) (result i32)",
      "    (local $len i32) (local $i i32) (local $acc i32) (local $payload i32)",
      "    (local $c i32) (local $box i32) (local $cell i32) (local $pe i32)",
      "    (local $failed i32)",
      "    (local.set $failed (i32.const 0))",
      "    (local.set $acc (i32.const 0))",
      "    (local.set $len (i32.load (local.get $s)))",
      "    (local.set $payload (i32.add (local.get $s) (i32.const 8)))",
      "    (block $exit",
      "      (if (i32.eqz (local.get $len))",
      "        (then (local.set $failed (i32.const 1)) (br $exit)))",
      "      (local.set $i (i32.const 0))",
      "      (block $loop_break",
      "        (loop $loop",
      "          (br_if $loop_break (i32.ge_u (local.get $i) (local.get $len)))",
      "          (local.set $c (i32.load8_u (i32.add (local.get $payload) (local.get $i))))",
      "          (if (i32.lt_u (local.get $c) (i32.const 48))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (if (i32.gt_u (local.get $c) (i32.const 57))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $acc",
      "            (i32.add",
      "              (i32.mul (local.get $acc) (i32.const 10))",
      "              (i32.sub (local.get $c) (i32.const 48))))",
      "          (if (i32.gt_u (local.get $acc) (i32.const 255))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "          (br $loop))))",
      "    (if (result i32) (local.get $failed)",
      "      (then",
      "        (local.set $pe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $pe) (i32.const " <> tShow (ptParseError ptags) <> "))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $pe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (local.get $acc))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | showUInt32: render an unsigned 32-bit value as decimal length-prefixed
--   string. Mirrors 'rtShowI32' but skips the negative-sign branch — the
--   input bit pattern is treated as unsigned end-to-end (i32.div_u /
--   i32.rem_u), so values 2147483648..4294967295 render correctly
--   without an erroneous '-' prefix.
rtShowU32 :: Text
rtShowU32 =
  unlines
    [ "  (func $__show_u32 (param $p i32) (result i32)",
      "    (local $v i32) (local $buf i32) (local $pos i32) (local $digit i32) (local $blen i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (local.set $buf (call $__alloc (i32.const 24)))",
      "    (local.set $pos (i32.const 23))",
      "    (if (i32.eqz (local.get $v))",
      "      (then",
      "        (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.const 48))",
      "        (local.set $pos (i32.sub (local.get $pos) (i32.const 1))))",
      "      (else",
      "        (block $done",
      "          (loop $loop",
      "            (br_if $done (i32.eqz (local.get $v)))",
      "            (local.set $digit (i32.rem_u (local.get $v) (i32.const 10)))",
      "            (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.add (local.get $digit) (i32.const 48)))",
      "            (local.set $pos (i32.sub (local.get $pos) (i32.const 1)))",
      "            (local.set $v (i32.div_u (local.get $v) (i32.const 10)))",
      "            (br $loop)))))",
      "    (local.set $blen (i32.sub (i32.const 23) (local.get $pos)))",
      "    (call $__memcpy (i32.add (local.get $buf) (i32.const 8))",
      "                    (i32.add (local.get $buf) (i32.add (local.get $pos) (i32.const 1)))",
      "                    (local.get $blen))",
      "    (i32.store (local.get $buf) (local.get $blen))",
      "    (i32.store offset=4 (local.get $buf) (local.get $blen))",
      "    (local.get $buf))"
    ]

-- | predUInt32: Either UnderflowError UInt32. Mirrors 'rtPredU8' since
--   the underflow boundary is also 0; the only difference is that the
--   stored cell is interpreted as unsigned 32-bit, but i32.eqz / i32.sub
--   work bit-pattern-identically for u32.
rtPredU32 :: PreludeTags -> Text
rtPredU32 ptags =
  unlines
    [ "  (func $__predUInt32 (param $p i32) (result i32)",
      "    (local $v i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eqz (local.get $v))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const " <> tShow (ptUnderflowError ptags) <> "))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | succUInt32: Either OverflowError UInt32. Boundary is 4294967295,
--   encoded as 'i32.const -1' (same bit pattern). On the ok path
--   '(v + 1)' wraps modulo 2^32 in i32 arithmetic — but since we already
--   checked v != 4294967295, the result is in 1..4294967295 and the
--   wrap is irrelevant.
rtSuccU32 :: PreludeTags -> Text
rtSuccU32 ptags =
  unlines
    [ "  (func $__succUInt32 (param $p i32) (result i32)",
      "    (local $v i32) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eq (local.get $v) (i32.const -1))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const " <> tShow (ptOverflowError ptags) <> "))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.add (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | addUInt32: Either OverflowError UInt32. Widen both operands to i64
--   (extend_i32_u, unsigned), sum at 64-bit width, compare against
--   4294967295. On the ok path 'i32.wrap_i64' truncates the low 32 bits,
--   which is exactly the in-range result.
rtAddU32 :: PreludeTags -> Text
rtAddU32 ptags =
  unlines
    [ "  (func $__addUInt32 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $s i64) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $s",
      "      (i64.add",
      "        (i64.extend_i32_u (i32.load (local.get $pa)))",
      "        (i64.extend_i32_u (i32.load (local.get $pb)))))",
      "    (if (result i32) (i64.gt_u (local.get $s) (i64.const 4294967295))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const " <> tShow (ptOverflowError ptags) <> "))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.wrap_i64 (local.get $s)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | subUInt32: Either UnderflowError UInt32. 'i32.lt_u' compares the
--   stored cells as unsigned; the difference is computed at i32 width
--   (the bit pattern matches u32 subtraction when a >= b).
rtSubU32 :: PreludeTags -> Text
rtSubU32 ptags =
  unlines
    [ "  (func $__subUInt32 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $a i32) (local $b i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $a (i32.load (local.get $pa)))",
      "    (local.set $b (i32.load (local.get $pb)))",
      "    (if (result i32) (i32.lt_u (local.get $a) (local.get $b))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const " <> tShow (ptUnderflowError ptags) <> "))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (local.get $a) (local.get $b)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | mulUInt32: Either OverflowError UInt32. Promote both operands to
--   i64 (extend_i32_u) so the unmasked product up to (2^32-1)^2 fits,
--   compare against 4294967295.
rtMulU32 :: PreludeTags -> Text
rtMulU32 ptags =
  unlines
    [ "  (func $__mulUInt32 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $p i64) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $p",
      "      (i64.mul",
      "        (i64.extend_i32_u (i32.load (local.get $pa)))",
      "        (i64.extend_i32_u (i32.load (local.get $pb)))))",
      "    (if (result i32) (i64.gt_u (local.get $p) (i64.const 4294967295))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const " <> tShow (ptOverflowError ptags) <> "))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.wrap_i64 (local.get $p)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | parseUInt32 : String -> Either ParseError UInt32. Same shape as
--   'rtParseUInt8' but with an i64 accumulator so the running magnitude
--   (up to 4294967295 * 10 + 9 = 42949672959) fits before the
--   '> 4294967295' fast-fail check.
rtParseUInt32 :: PreludeTags -> Text
rtParseUInt32 ptags =
  unlines
    [ "  (func $__parseUInt32 (param $s i32) (result i32)",
      "    (local $len i32) (local $i i32) (local $acc i64) (local $payload i32)",
      "    (local $c i32) (local $box i32) (local $cell i32) (local $pe i32)",
      "    (local $failed i32)",
      "    (local.set $failed (i32.const 0))",
      "    (local.set $acc (i64.const 0))",
      "    (local.set $len (i32.load (local.get $s)))",
      "    (local.set $payload (i32.add (local.get $s) (i32.const 8)))",
      "    (block $exit",
      "      (if (i32.eqz (local.get $len))",
      "        (then (local.set $failed (i32.const 1)) (br $exit)))",
      "      (local.set $i (i32.const 0))",
      "      (block $loop_break",
      "        (loop $loop",
      "          (br_if $loop_break (i32.ge_u (local.get $i) (local.get $len)))",
      "          (local.set $c (i32.load8_u (i32.add (local.get $payload) (local.get $i))))",
      "          (if (i32.lt_u (local.get $c) (i32.const 48))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (if (i32.gt_u (local.get $c) (i32.const 57))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $acc",
      "            (i64.add",
      "              (i64.mul (local.get $acc) (i64.const 10))",
      "              (i64.extend_i32_u (i32.sub (local.get $c) (i32.const 48)))))",
      "          (if (i64.gt_u (local.get $acc) (i64.const 4294967295))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "          (br $loop))))",
      "    (if (result i32) (local.get $failed)",
      "      (then",
      "        (local.set $pe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $pe) (i32.const " <> tShow (ptParseError ptags) <> "))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $pe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.wrap_i64 (local.get $acc)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | eqInt32 / eqUInt8: two boxed integers → Bool (one-slot container).
--   Int32 and UInt8 both flow as pointers to an i32 cell; UInt8 values are
--   stored masked to 0..255, so a plain i32.eq gives the same answer as
--   native u8 equality. True=0, False=1 matches declaration order in
--   `type Bool = True | False`.
rtEqI32 :: PreludeTags -> Text
rtEqI32 ptags =
  unlines
    [ "  (func $__eq_i32 (param $a i32) (param $b i32) (result i32)",
      "    (local $cell i32)",
      "    (local.set $cell (call $__alloc (i32.const 4)))",
      "    (if (result i32) (i32.eq (i32.load (local.get $a)) (i32.load (local.get $b)))",
      "      (then",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptTrue ptags) <> "))",
      "        (local.get $cell))",
      "      (else",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptFalse ptags) <> "))",
      "        (local.get $cell))))"
    ]

-- | '__getArgs' is the zero-arg runtime helper for
--   'BuiltIn.internalGetArgs', called from 'runIO''s 'IOGetArgs' arm.
--   Re-reads argv via WASI 'args_get' through '$__get_arg' and routes
--   it through '$__entryArgEither' for strict-UTF-16 validation. Per
--   the no-memoisation decision each call yields a fresh 'Either'
--   cell — argv is invariant during execution so repeat calls are
--   deterministically equal.
rtGetArgs :: Text
rtGetArgs =
  unlines
    [ "  (func $__getArgs (result i32)",
      "    (call $__entryArgEither (call $__get_arg)))"
    ]

rtGetArg :: Int -> Text
rtGetArg emptyOff =
  unlines
    [ "  (func $__get_arg (result i32)",
      "    (local $argv_buf i32) (local $ptrs i32)",
      "    (drop (call $args_sizes_get (i32.const 12) (i32.const 16)))",
      "    (if (result i32) (i32.lt_u (i32.load (i32.const 12)) (i32.const 2))",
      "      (then (i32.const " <> show emptyOff <> "))",
      "      (else",
      "        (local.set $argv_buf (call $__alloc (i32.load (i32.const 16))))",
      "        (local.set $ptrs (call $__alloc (i32.mul (i32.load (i32.const 12)) (i32.const 4))))",
      "        (drop (call $args_get (local.get $ptrs) (local.get $argv_buf)))",
      "        (i32.load (i32.add (local.get $ptrs) (i32.const 4))))))"
    ]

-- | '__entryArgEither' wraps argv[1] in 'Either (StringTooLong |
--   UnpairedUtf16Surrogate) String' for the user's 'main'. Single
--   UTF-8 byte scan that runs both checks:
--     1. UTF-16 code unit count vs 'maxStringLengthUtf16CodeUnits' (2^27),
--        with a short-circuit on overflow.
--     2. Surrogate-encoded byte triplets ('ED A0..BF 80..BF'). Standard
--        UTF-8 (RFC 3629) forbids these; WTF-8 / CESU-8 / Java modified
--        UTF-8 emit them. Sets a sticky flag (no early exit, so a
--        longer-than-cap input still reports 'StringTooLong' — cap-check
--        has priority).
--   Mirrors LLVM's helper byte-for-byte semantically; cap value
--   (134217728 = 2^27) and FNV-1a row tags for "StringTooLong" /
--   "UnpairedUtf16Surrogate" must stay in sync with
--   'maxStringLengthUtf16CodeUnits' in 'stdlib/Prelude.aww'.
--
--   Layout (linear-memory cells; identical for both Left arms, only the
--   row tag differs):
--     Right s : alloc(8); [tag=1, ptr=s]
--     Left e  : alloc(8); [tag=0, ptr=row]
--               row   : alloc(8); [rowTag, ptr=inner]   (CRow box)
--               inner : alloc(4); [tag=0]              (singleton CCon)
rtEntryArgEither :: PreludeTags -> Text
rtEntryArgEither ptags =
  unlines
    [ "  (func $__entryArgEither (param $arg i32) (result i32)",
      "    (local $i i32) (local $n i32) (local $b i32) (local $surr i32)",
      "    (local $inner i32) (local $row i32) (local $cell i32)",
      "    (local $wrapped i32)",
      "    (local.set $i (i32.const 0))",
      "    (local.set $n (i32.const 0))",
      "    (local.set $surr (i32.const 0))",
      "    (block $break_scan",
      "      (loop $scan_loop",
      "        (local.set $b (i32.load8_u (i32.add (local.get $arg) (local.get $i))))",
      "        (br_if $break_scan (i32.eqz (local.get $b)))",
      "        (if (i32.ne (i32.and (local.get $b) (i32.const 0xC0)) (i32.const 0x80))",
      "          (then",
      "            (if (i32.eq (local.get $b) (i32.const 0xED))",
      "              (then",
      "                (if (i32.eq (i32.and (i32.load8_u (i32.add (local.get $arg) (i32.add (local.get $i) (i32.const 1)))) (i32.const 0xE0)) (i32.const 0xA0))",
      "                  (then (local.set $surr (i32.const 1))))))",
      "            (if (i32.eq (i32.and (local.get $b) (i32.const 0xF8)) (i32.const 0xF0))",
      "              (then (local.set $n (i32.add (local.get $n) (i32.const 2))))",
      "              (else (local.set $n (i32.add (local.get $n) (i32.const 1)))))",
      "            (br_if $break_scan (i32.gt_u (local.get $n) (i32.const 134217728)))))",
      "        (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "        (br $scan_loop)))",
      "    (if (result i32) (i32.gt_u (local.get $n) (i32.const 134217728))",
      "      (then",
      "        (local.set $inner (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $inner) (i32.const " <> tShow (ptStringTooLong ptags) <> "))",
      "        (local.set $row (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $row) (i32.const " <> show stringTooLongTag <> "))",
      "        (i32.store offset=4 (local.get $row) (local.get $inner))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $row))",
      "        (local.get $cell))",
      "      (else",
      "        (if (result i32) (local.get $surr)",
      "          (then",
      "            (local.set $inner (call $__alloc (i32.const 4)))",
      "            (i32.store (local.get $inner) (i32.const " <> tShow (ptUnpairedUtf16Surrogate ptags) <> "))",
      "            (local.set $row (call $__alloc (i32.const 8)))",
      "            (i32.store (local.get $row) (i32.const " <> show unpairedSurrogateTag <> "))",
      "            (i32.store offset=4 (local.get $row) (local.get $inner))",
      "            (local.set $cell (call $__alloc (i32.const 8)))",
      "            (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "            (i32.store offset=4 (local.get $cell) (local.get $row))",
      "            (local.get $cell))",
      "          (else",
      "            (local.set $wrapped (call $__alloc (i32.add (local.get $i) (i32.const 8))))",
      "            (i32.store (local.get $wrapped) (local.get $i))",
      "            (i32.store offset=4 (local.get $wrapped) (local.get $n))",
      "            (call $__memcpy (i32.add (local.get $wrapped) (i32.const 8)) (local.get $arg) (local.get $i))",
      "            (local.set $cell (call $__alloc (i32.const 8)))",
      "            (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "            (i32.store offset=4 (local.get $cell) (local.get $wrapped))",
      "            (local.get $cell))))))"
    ]
  where
    stringTooLongTag :: Word32
    stringTooLongTag = rowTag (TyCon noSpan "StringTooLong")
    unpairedSurrogateTag :: Word32
    unpairedSurrogateTag = rowTag (TyCon noSpan "UnpairedUtf16Surrogate")

startFunc :: Text
startFunc =
  unlines
    [ "  (func $_start (export \"_start\")",
      -- v_main is a zero-arg value (CValDef) that builds the IO tree;
      -- 'runIO' walks it to execute the effects (returns Unit which
      -- we discard). User code that wants argv reads it through
      -- 'IO.Args.getArgs' inside the IO chain — that lowers to an
      -- 'IOGetArgs' constructor whose 'runIO' arm calls '$__getArgs'
      -- (which re-reads WASI 'args_get' on every call).
      "    (drop (call $" <> mangle "runIO" <> " (call $" <> mangle "main" <> "))))"
    ]

-- ════════════════════════════════════════════════════════════════════════════
-- User declarations
-- ════════════════════════════════════════════════════════════════════════════

emitDecl :: WasmCtx -> CDecl -> Text
emitDecl ctx = \case
  -- TCO-wrapped body. WASM parameters double as mutable locals, so a
  -- 'CContinue' can rebind them directly; we only need extra @$__k@
  -- locals to stage new values so that cross-parameter reads see the
  -- old bindings. The whole body runs inside @(loop $tco_top ...)@, and
  -- @br $tco_top@ restarts it instead of recursing.
  CFunDef nm args (CLoop body) ->
    let paramSet = Set.fromList args
        localCtx = ctx {wParams = paramSet, wLocalExprs = Map.empty}
        wasmParams = T.intercalate " " (map (\a -> "(param $" <> mangle a <> " i32)") args)
        locals = collectLocals body
        tcoTemps =
          T.concat
            [ "\n    (local $__k" <> show (i :: Int) <> " i32)"
            | i <- [0 .. length args - 1]
            ]
     in "  (func $"
          <> mangle nm
          <> " "
          <> wasmParams
          <> " (result i32)"
          <> locals
          <> tcoTemps
          <> "\n    (loop $tco_top (result i32) "
          <> emitTailWat localCtx args body
          <> "))"
  CFunDef nm args body ->
    let paramSet = Set.fromList args
        localCtx = ctx {wParams = paramSet, wLocalExprs = Map.empty}
        wasmParams = T.intercalate " " (map (\a -> "(param $" <> mangle a <> " i32)") args)
        locals = collectLocals body
     in "  (func $"
          <> mangle nm
          <> " "
          <> wasmParams
          <> " (result i32)"
          <> locals
          <> "\n    "
          <> emitExpr localCtx body
          <> ")"
  CValDef nm rhs ->
    let localCtx = ctx {wParams = Set.empty, wLocalExprs = Map.empty}
        locals = collectLocals rhs
     in "  (func $"
          <> mangle nm
          <> " (result i32)"
          <> locals
          <> "\n    "
          <> emitExpr localCtx rhs
          <> ")"

-- | Emit @body@ in tail position under a @(loop $tco_top ...)@.
-- 'CContinue' rebinds the loop's parameters and jumps back to the loop
-- head; any other tail shape produces an @i32@ value that becomes the
-- function's result. 'CCase' chains structurally so each arm is itself
-- emitted in tail form — either a value or a @br@ terminator.
emitTailWat :: WasmCtx -> [Text] -> CExpr -> Text
emitTailWat ctx0 params = go ctx0
  where
    go :: WasmCtx -> CExpr -> Text
    go ctx = \case
      CContinue newArgs ->
        let temps = ["$__k" <> show (i :: Int) | i <- [0 .. length newArgs - 1]]
            evals =
              [ "(local.set " <> t <> " " <> emitExpr ctx a <> ")"
              | (t, a) <- zip temps newArgs
              ]
            rebinds =
              [ "(local.set $" <> mangle p <> " (local.get " <> t <> "))"
              | (p, t) <- zip params temps
              ]
         in T.intercalate " " (evals <> rebinds <> ["(br $tco_top)"])
      CCase scrut alts ->
        let sorted = sortWith (\(t, _, _) -> t) alts
            scrutCode = emitExpr ctx scrut
         in "(block (result i32) (local.set $__scrut "
              <> scrutCode
              <> ") "
              <> buildTailChain ctx sorted
              <> ")"
      -- 'CRow' / 'CRowCase' share the runtime layout with one-field
      -- 'CCon' / 'CCase' (tag at offset 0, value at offset 4) so we
      -- can lower them through the same emit machinery; the tag width
      -- is 32 bits in both cases, just hash- vs. position-derived.
      CRow tag v -> go ctx (CCon (fromIntegral tag) [v])
      CRowCase scrut alts ->
        go ctx (CCase scrut [(fromIntegral t, [v], b) | (t, v, b) <- alts])
      other -> emitExpr ctx other

    buildTailChain :: WasmCtx -> [(Int, [Text], CExpr)] -> Text
    buildTailChain _ [] = "(unreachable)"
    buildTailChain ctx [(_, vars, body)] =
      armEntry vars <> go (bindVars ctx vars) body
    buildTailChain ctx ((tag, vars, body) : rest) =
      "(if (result i32) (i32.eq (i32.load (local.get $__scrut)) (i32.const "
        <> show tag
        <> ")) (then "
        <> armEntry vars
        <> go (bindVars ctx vars) body
        <> ") (else "
        <> buildTailChain ctx rest
        <> "))"

-- ════════════════════════════════════════════════════════════════════════════
-- Expressions
-- ════════════════════════════════════════════════════════════════════════════

emitExpr :: WasmCtx -> CExpr -> Text
emitExpr ctx = \case
  CString s ->
    let offset = fromMaybe (error $ "string not in pool: " <> show s) (Map.lookup s ctx.wStringPool)
     in "(i32.const " <> show offset <> ")"
  CVar n
    | Just expr <- Map.lookup n ctx.wLocalExprs -> expr
    | n `Set.member` ctx.wParams ->
        "(local.get $" <> mangle n <> ")"
    | n `Set.member` ctx.wValDefs ->
        "(call $" <> mangle n <> ")"
    | n `Set.member` ctx.wFunDefs ->
        let idx = fromMaybe 0 (Map.lookup n ctx.wTableMap)
         in "(i32.const " <> show idx <> ")"
    | otherwise ->
        "(i32.const 0)"
  CBuiltIn _ ->
    "(i32.const 0)" -- invariant: not a standalone term; dispatched from CCall
  CIntLit n _ ->
    let n32 = fromInteger n :: Int32
     in "(call $__box_i32 (i32.const " <> show n32 <> "))"
  CCon tag fields ->
    let conLocal = "$__con_" <> show ctx.wConDepth
        nestedCtx = ctx {wConDepth = ctx.wConDepth + 1}
        nSlots = 1 + length fields
        storeTag = "(i32.store (local.tee " <> conLocal <> " (call $__alloc (i32.const " <> show (nSlots * 4 :: Int) <> "))) (i32.const " <> show tag <> "))"
        storeFields =
          [ "(i32.store offset=" <> show (i * 4 :: Int) <> " (local.get " <> conLocal <> ") " <> emitExpr nestedCtx fld <> ")"
          | (fld, i) <- zip fields [1 :: Int ..]
          ]
     in "(block (result i32) " <> T.intercalate " " (storeTag : storeFields <> ["(local.get " <> conLocal <> ")"]) <> ")"
  -- 'CRow' / 'CRowCase' share the runtime layout with one-field
  -- 'CCon' / 'CCase' (tag at offset 0, value at offset 4) so we can
  -- lower them through the same emit machinery.
  CRow tag v -> emitExpr ctx (CCon (fromIntegral tag) [v])
  CRowCase scrut alts ->
    emitExpr ctx (CCase scrut [(fromIntegral t, [v], b) | (t, v, b) <- alts])
  CCase scrut alts ->
    emitCaseExpr ctx scrut alts
  CCall f xs ->
    case f of
      CBuiltIn "internalStdoutPrint"
        | [x] <- xs ->
            "(call $__print " <> emitExpr ctx x <> ")"
      -- 'BuiltIn.internalGetArgs' — call '$__getArgs', which
      -- re-reads argv via WASI and routes it through
      -- '$__entryArgEither'.
      CBuiltIn "internalGetArgs"
        | [] <- xs -> "(call $__getArgs)"
      CBuiltIn name
        | name == "showInt32" || name == "showUInt8",
          [x] <- xs ->
            "(call $__show_i32 " <> emitExpr ctx x <> ")"
      CBuiltIn "showUInt32"
        | [x] <- xs ->
            "(call $__show_u32 " <> emitExpr ctx x <> ")"
      CBuiltIn "predInt32"
        | [x] <- xs ->
            "(call $__predInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn "predUInt8"
        | [x] <- xs ->
            "(call $__predUInt8 " <> emitExpr ctx x <> ")"
      CBuiltIn "predUInt32"
        | [x] <- xs ->
            "(call $__predUInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn "succInt32"
        | [x] <- xs ->
            "(call $__succInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn "succUInt8"
        | [x] <- xs ->
            "(call $__succUInt8 " <> emitExpr ctx x <> ")"
      CBuiltIn "succUInt32"
        | [x] <- xs ->
            "(call $__succUInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn name
        | name == "eqInt32" || name == "eqUInt8" || name == "eqUInt32",
          [a, b] <- xs ->
            "(call $__eq_i32 " <> emitExpr ctx a <> " " <> emitExpr ctx b <> ")"
      CBuiltIn name
        | name == "addInt32" || name == "addUInt8" || name == "addUInt32" || name == "subInt32" || name == "subUInt8" || name == "subUInt32" || name == "mulUInt8" || name == "mulUInt32" || name == "mulInt32",
          [a, b] <- xs ->
            let fn = case name of
                  "addInt32" -> "$__addInt32"
                  "addUInt8" -> "$__addUInt8"
                  "addUInt32" -> "$__addUInt32"
                  "subInt32" -> "$__subInt32"
                  "subUInt8" -> "$__subUInt8"
                  "subUInt32" -> "$__subUInt32"
                  "mulInt32" -> "$__mulInt32"
                  "mulUInt32" -> "$__mulUInt32"
                  _ -> "$__mulUInt8"
             in "(call " <> fn <> " " <> emitExpr ctx a <> " " <> emitExpr ctx b <> ")"
      CBuiltIn "negInt32"
        | [x] <- xs ->
            "(call $__negInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn "splitOnFirst"
        | [a, b] <- xs ->
            "(call $__splitOnFirst " <> emitExpr ctx a <> " " <> emitExpr ctx b <> ")"
      CBuiltIn name
        | name == "parseInt32" || name == "parseUInt8" || name == "parseUInt32",
          [x] <- xs ->
            let fn = case name of
                  "parseInt32" -> "$__parseInt32"
                  "parseUInt32" -> "$__parseUInt32"
                  _ -> "$__parseUInt8"
             in "(call " <> fn <> " " <> emitExpr ctx x <> ")"
      CBuiltIn name
        | name == "lengthCodePoints" || name == "lengthUtf16CodeUnits" || name == "lengthUtf8Bytes",
          [x] <- xs ->
            let fn = case name of
                  "lengthCodePoints" -> "$__lengthCodePoints"
                  "lengthUtf16CodeUnits" -> "$__lengthUtf16CodeUnits"
                  _ -> "$__lengthUtf8Bytes"
             in "(call " <> fn <> " " <> emitExpr ctx x <> ")"
      CBuiltIn "concatString"
        | [a, b] <- xs ->
            "(call $__concat " <> emitExpr ctx a <> " " <> emitExpr ctx b <> ")"
      CBuiltIn n ->
        error ("WASM codegen: unknown builtin '" <> n <> "' reached CCall (typecheck should have rejected it)")
      CVar n
        | n `Set.member` ctx.wFunDefs ->
            "(call $" <> mangle n <> " " <> T.intercalate " " (map (emitExpr ctx) xs) <> ")"
      _ ->
        let arity = length xs
         in "(call_indirect (type $arity_"
              <> show arity
              <> ") "
              <> T.intercalate " " (map (emitExpr ctx) xs)
              <> " "
              <> emitExpr ctx f
              <> ")"
  CLoop _ -> error "WASM codegen: CLoop survived untcoProgram (pipeline bug)"
  CContinue _ -> error "WASM codegen: CContinue survived untcoProgram (pipeline bug)"

-- | Emit a case expression as nested @if\/else@ in WAT.
--   Stores the scrutinee in @$__scrut@, extracts the tag from offset 0,
--   materialises each bound variable into its own WASM local on arm
--   entry (pre-declared by 'collectLocals'), and then runs the body.
--   This keeps outer-arm bindings safe when the inner body overwrites
--   @$__scrut@ with its own scrutinee.
emitCaseExpr :: WasmCtx -> CExpr -> [(Int, [Text], CExpr)] -> Text
emitCaseExpr ctx scrut alts =
  let sorted = sortWith (\(t, _, _) -> t) alts
      scrutCode = emitExpr ctx scrut
   in "(block (result i32) (local.set $__scrut " <> scrutCode <> ") " <> buildChain sorted <> ")"
  where
    buildChain [] = "(unreachable)"
    buildChain [(_, vars, body)] =
      armEntry vars <> emitExpr (bindVars ctx vars) body
    buildChain ((tag, vars, body) : rest) =
      "(if (result i32) (i32.eq (i32.load (local.get $__scrut)) (i32.const "
        <> show tag
        <> ")) (then "
        <> armEntry vars
        <> emitExpr (bindVars ctx vars) body
        <> ") (else "
        <> buildChain rest
        <> "))"

-- | Emit @local.set@ for each arm-bound variable, pulling values out of
-- the current @$__scrut@ into their pre-declared @$v_<name>@ slots
-- before any nested 'CCase' gets a chance to overwrite @$__scrut@.
armEntry :: [Text] -> Text
armEntry vars =
  T.concat
    [ "(local.set $"
        <> mangle v
        <> " (i32.load offset="
        <> show (i * 4 :: Int)
        <> " (local.get $__scrut))) "
    | (v, i) <- zip vars [1 :: Int ..]
    ]

-- | Register each arm-bound name in 'wLocalExprs' as a bare
-- @(local.get $v_<name>)@. The slot was already written by 'armEntry',
-- so every subsequent use of the binder reads its own local (not the
-- shared @$__scrut@).
bindVars :: WasmCtx -> [Text] -> WasmCtx
bindVars ctx vars =
  let entries =
        [ (v, "(local.get $" <> mangle v <> ")")
        | v <- vars
        ]
   in ctx {wLocalExprs = foldl' (\m (k, e) -> Map.insert k e m) ctx.wLocalExprs entries}

-- | Determine which locals a function body needs and emit their declarations.
-- Each 'CCase' arm's bindings are materialised into a per-binding named
-- local on arm entry (see 'bindVars'); nested 'CCase's would clobber each
-- other if bindings stayed as inline @i32.load@ expressions against a
-- shared @$__scrut@. Pre-declaring @$v_<name>@ for every bound name means
-- the inner case is free to overwrite @$__scrut@ without corrupting outer
-- arm bindings.
collectLocals :: CExpr -> Text
collectLocals body =
  let depth = maxConDepth body
      conLocals = T.concat ["\n    (local $__con_" <> show i <> " i32)" | i <- [0 .. depth - 1]]
      ns = hasCCase body
      bindLocals =
        T.concat
          [ "\n    (local $" <> mangle v <> " i32)"
          | v <- Set.toAscList (caseBoundVars body)
          ]
   in conLocals
        <> bindLocals
        <> (if ns then "\n    (local $__scrut i32)" else "")

-- | Every case-arm binding name reachable from @e@. Used by 'collectLocals'
-- to pre-declare a WASM local per binding so arm-entry can materialise
-- values into their own slots, immune to later 'CCase' scrutinee writes.
caseBoundVars :: CExpr -> Set Text
caseBoundVars = \case
  CCase s alts ->
    caseBoundVars s
      <> foldMap (\(_, vs, b) -> Set.fromList vs <> caseBoundVars b) alts
  CRowCase s alts ->
    caseBoundVars s
      <> foldMap (\(_, v, b) -> Set.singleton v <> caseBoundVars b) alts
  CRow _ v -> caseBoundVars v
  CCall f xs -> caseBoundVars f <> foldMap caseBoundVars xs
  CCon _ fs -> foldMap caseBoundVars fs
  CLoop b -> caseBoundVars b
  CContinue xs -> foldMap caseBoundVars xs
  _ -> mempty

-- | Compute the maximum CCon nesting depth in an expression.
maxConDepth :: CExpr -> Int
maxConDepth = \case
  CCon _ fields -> 1 + foldl' max 0 (map maxConDepth fields)
  CRow _ v -> 1 + maxConDepth v
  CCase s alts -> max (maxConDepth s) (foldl' max 0 [maxConDepth b | (_, _, b) <- alts])
  CRowCase s alts -> max (maxConDepth s) (foldl' max 0 [maxConDepth b | (_, _, b) <- alts])
  CCall f xs -> foldl' max (maxConDepth f) (map maxConDepth xs)
  _ -> 0

hasCCase :: CExpr -> Bool
hasCCase = \case
  CCase {} -> True
  CRowCase {} -> True
  CCall f xs -> hasCCase f || any hasCCase xs
  _ -> False

-- ════════════════════════════════════════════════════════════════════════════
-- Name mangling
-- ════════════════════════════════════════════════════════════════════════════

-- | All names get @v_@ prefix (including @main@ → @v_main@),
--   because @_start@ is the WASI entry point.
mangle :: Text -> Text
mangle t =
  let ok c = Char.isAlphaNum c || c == '_' || c == '\''
      body = T.map (\c -> if ok c then c else '_') t
   in "v_" <> body
